phase1.code:
# Making decisions with if, elif, else

player_health = 75

# Basic if statement
if player_health > 50:
    print("You're in good shape!")

# if-else
if player_health > 50:
    print("You're in good shape!")
else:
    print("You should heal soon.")

# if-elif-else (multiple conditions)
player_health = 30

if player_health > 75:
    print("Perfect health!")
elif player_health > 50:
    print("You're in good shape!")
elif player_health > 25:
    print("You're a bit hurt.")
else:
    print("Critical condition! Heal now!")

# Comparing strings
spell = "fireball"

if spell == "fireball":
    print("🔥 Fireball! 50 damage")
elif spell == "icebolt":
    print("❄️ Icebolt! 30 damage")
elif spell == "heal":
    print("💚 Heal! +20 health")
else:
    print("Unknown spell")

# Multiple conditions with logical operators
level = 10
has_key = True

if level >= 10 and has_key:
    print("You can enter the dungeon!")
else:
    print("You need level 10 and a key.")

